1	use axum::{
2	    Json, Router,
3	    body::Bytes,
4	    extract::{Path, State},
5	    http::{StatusCode, Uri},
6	    response::{IntoResponse, Response},
7	    routing::{get, put},
8	};
9	use serde::Serialize;
10	use serde_json::{Value, json};
11	use std::{
12	    env,
13	    error::Error,
14	    path::PathBuf,
15	    sync::{
16	        Arc,
17	        atomic::{AtomicU64, Ordering},
18	    },
19	    time::SystemTime,
20	};
21	
22	#[derive(Serialize)]
23	struct Health {
24	    status: &'static str,
25	}
26	
27	#[derive(Serialize)]
28	struct Version {
29	    name: &'static str,
30	    version: &'static str,
31	}
32	
33	async fn health() -> Json<Health> {
34	    Json(Health { status: "ok" })
35	}
36	
37	async fn version() -> Json<Version> {
38	    Json(Version {
39	        name: env!("CARGO_PKG_NAME"),
40	        version: env!("CARGO_PKG_VERSION"),
41	    })
42	}
43	
44	#[derive(Clone)]
45	struct AppState {
46	    data_dir: Arc<PathBuf>,
47	}
48	
49	fn error_response(status: StatusCode, code: &'static str) -> Response {
50	    (status, Json(json!({ "error": code }))).into_response()
51	}
52	
53	fn valid_identifier(s: &str) -> bool {
54	    !s.is_empty()
55	        && s.bytes()
56	            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
57	}
58	
59	fn record_path(state: &AppState, name: &str, key: &str) -> PathBuf {
60	    state.data_dir.join(name).join(format!("{key}.json"))
61	}
62	
63	async fn put_record(
64	    State(state): State<AppState>,
65	    Path((name, key)): Path<(String, String)>,
66	    body: Bytes,
67	) -> Response {
68	    if !valid_identifier(&name) || !valid_identifier(&key) {
69	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
70	    }
71	    if body.is_empty() {
72	        return error_response(StatusCode::BAD_REQUEST, "invalid_json");
73	    }
74	    let value: Value = match serde_json::from_slice(&body) {
75	        Ok(v) => v,
76	        Err(_) => return error_response(StatusCode::BAD_REQUEST, "invalid_json"),
77	    };
78	
79	    if let Err(resp) = persist_record(&state, &name, &key, &body).await {
80	        return resp;
81	    }
82	    Json(json!({ "key": key, "value": value })).into_response()
83	}
84	
85	/// Write the record atomically: temp file + fsync + rename + dir fsync, so a
86	/// crash either leaves the old value intact or the new one fully in place.
87	async fn persist_record(
88	    state: &AppState,
89	    name: &str,
90	    key: &str,
91	    body: &[u8],
92	) -> Result<(), Response> {
93	    let dir = state.data_dir.join(name);
94	    if let Err(e) = tokio::fs::create_dir_all(&dir).await {
95	        tracing_error(&e);
96	        return Err(error_response(
97	            StatusCode::INTERNAL_SERVER_ERROR,
98	            "internal",
99	        ));
100	    }
101	
102	    static TMP_COUNTER: AtomicU64 = AtomicU64::new(0);
103	    let tmp = dir.join(format!(
104	        ".tmp-{}-{}",
105	        std::process::id(),
106	        TMP_COUNTER.fetch_add(1, Ordering::Relaxed)
107	    ));
108	
109	    let result = async {
110	        let mut file = tokio::fs::File::create(&tmp).await?;
111	        tokio::io::AsyncWriteExt::write_all(&mut file, body).await?;
112	        file.sync_all().await?;
113	        tokio::fs::rename(&tmp, record_path(state, name, key)).await?;
114	        // Fsync the directory so the rename itself is durable.
115	        let dir_file = tokio::fs::File::open(&dir).await?;
116	        dir_file.sync_all().await?;
117	        Ok::<(), std::io::Error>(())
118	    }
119	    .await;
120	
121	    if let Err(e) = result {
122	        let _ = tokio::fs::remove_file(&tmp).await;
123	        tracing_error(&e);
124	        return Err(error_response(
125	            StatusCode::INTERNAL_SERVER_ERROR,
126	            "internal",
127	        ));
128	    }
129	    Ok(())
130	}
131	
132	fn tracing_error(e: &std::io::Error) {
133	    eprintln!("storage error: {e}");
134	}
135	
136	async fn get_record(
137	    State(state): State<AppState>,
138	    Path((name, key)): Path<(String, String)>,
139	) -> Response {
140	    if !valid_identifier(&name) || !valid_identifier(&key) {
141	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
142	    }
143	
144	    let bytes = match tokio::fs::read(record_path(&state, &name, &key)).await {
145	        Ok(b) => b,
146	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
147	            return error_response(StatusCode::NOT_FOUND, "not_found");
148	        }
149	        Err(e) => {
150	            tracing_error(&e);
151	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
152	        }
153	    };
154	    match serde_json::from_slice::<Value>(&bytes) {
155	        Ok(value) => Json(json!({ "key": key, "value": value })).into_response(),
156	        Err(e) => {
157	            eprintln!("corrupt record {name}/{key}: {e}");
158	            error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal")
159	        }
160	    }
161	}
162	
163	/// Format a timestamp as RFC3339 UTC with second precision, e.g.
164	/// `2006-01-02T15:04:05Z`. Civil-from-days conversion per Howard Hinnant.
165	fn format_rfc3339_utc(t: SystemTime) -> String {
166	    let secs = t
167	        .duration_since(SystemTime::UNIX_EPOCH)
168	        .map(|d| d.as_secs())
169	        .unwrap_or(0);
170	    let days = (secs / 86400) as i64;
171	    let sod = secs % 86400;
172	    let (hour, min, sec) = (sod / 3600, (sod % 3600) / 60, sod % 60);
173	
174	    let z = days + 719468;
175	    let era = if z >= 0 { z } else { z - 146096 } / 146097;
176	    let doe = (z - era * 146097) as u64; // [0, 146096]
177	    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
178	    let year = yoe as i64 + era * 400;
179	    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
180	    let mp = (5 * doy + 2) / 153; // [0, 11]
181	    let day = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
182	    let month = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
183	    let year = if month <= 2 { year + 1 } else { year };
184	
185	    format!("{year:04}-{month:02}-{day:02}T{hour:02}:{min:02}:{sec:02}Z")
186	}
187	
188	/// Key-only filter for record listing, parsed from the query string.
189	/// Either a prefix match, or a lower/upper bound range (each bound
190	/// inclusive or exclusive), but never both.
191	#[derive(Default)]
192	struct KeyFilter {
193	    prefix: Option<String>,
194	    /// (bound, inclusive)
195	    lower: Option<(String, bool)>,
196	    /// (bound, inclusive)
197	    upper: Option<(String, bool)>,
198	}
199	
200	impl KeyFilter {
201	    fn matches(&self, key: &str) -> bool {
202	        if let Some(prefix) = &self.prefix {
203	            return key.starts_with(prefix.as_str());
204	        }
205	        if let Some((bound, inclusive)) = &self.lower {
206	            let ok = if *inclusive {
207	                key >= bound.as_str()
208	            } else {
209	                key > bound.as_str()
210	            };
211	            if !ok {
212	                return false;
213	            }
214	        }
215	        if let Some((bound, inclusive)) = &self.upper {
216	            let ok = if *inclusive {
217	                key <= bound.as_str()
218	            } else {
219	                key < bound.as_str()
220	            };
221	            if !ok {
222	                return false;
223	            }
224	        }
225	        true
226	    }
227	}
228	
229	fn hex_val(b: u8) -> Option<u8> {
230	    match b {
231	        b'0'..=b'9' => Some(b - b'0'),
232	        b'a'..=b'f' => Some(b - b'a' + 10),
233	        b'A'..=b'F' => Some(b - b'A' + 10),
234	        _ => None,
235	    }
236	}
237	
238	/// Decode one query-string component: `%XX` escapes and `+` as space.
239	fn percent_decode(s: &str) -> Result<String, ()> {
240	    let bytes = s.as_bytes();
241	    let mut out = Vec::with_capacity(bytes.len());
242	    let mut i = 0;
243	    while i < bytes.len() {
244	        match bytes[i] {
245	            b'%' => {
246	                if i + 2 >= bytes.len() {
247	                    return Err(());
248	                }
249	                let hi = hex_val(bytes[i + 1]).ok_or(())?;
250	                let lo = hex_val(bytes[i + 2]).ok_or(())?;
251	                out.push(hi << 4 | lo);
252	                i += 3;
253	            }
254	            b'+' => {
255	                out.push(b' ');
256	                i += 1;
257	            }
258	            b => {
259	                out.push(b);
260	                i += 1;
261	            }
262	        }
263	    }
264	    String::from_utf8(out).map_err(|_| ())
265	}
266	
267	/// Parse the query string into a key filter. Any parameter outside the
268	/// documented set (`prefix`, `gte`, `gt`, `lte`, `lt`), duplicates,
269	/// conflicting bounds, or values that are not valid key fragments
270	/// (non-empty, `[A-Za-z0-9_-]`) are rejected.
271	fn parse_key_filter(query: &str) -> Result<KeyFilter, ()> {
272	    let mut filter = KeyFilter::default();
273	    if query.is_empty() {
274	        return Ok(filter);
275	    }
276	    let mut gte: Option<String> = None;
277	    let mut gt: Option<String> = None;
278	    let mut lte: Option<String> = None;
279	    let mut lt: Option<String> = None;
280	
281	    for pair in query.split('&') {
282	        let (raw_name, raw_value) = pair.split_once('=').ok_or(())?;
283	        let name = percent_decode(raw_name)?;
284	        let value = percent_decode(raw_value)?;
285	        if !valid_identifier(&value) {
286	            return Err(());
287	        }
288	        let slot = match name.as_str() {
289	            "prefix" => &mut filter.prefix,
290	            "gte" => &mut gte,
291	            "gt" => &mut gt,
292	            "lte" => &mut lte,
293	            "lt" => &mut lt,
294	            _ => return Err(()),
295	        };
296	        if slot.is_some() {
297	            return Err(());
298	        }
299	        *slot = Some(value);
300	    }
301	
302	    if filter.prefix.is_some() && (gte.is_some() || gt.is_some() || lte.is_some() || lt.is_some())
303	    {
304	        return Err(());
305	    }
306	    if gte.is_some() && gt.is_some() {
307	        return Err(());
308	    }
309	    if lte.is_some() && lt.is_some() {
310	        return Err(());
311	    }
312	    filter.lower = gte.map(|b| (b, true)).or_else(|| gt.map(|b| (b, false)));
313	    filter.upper = lte.map(|b| (b, true)).or_else(|| lt.map(|b| (b, false)));
314	    Ok(filter)
315	}
316	
317	async fn list_records(
318	    State(state): State<AppState>,
319	    Path(name): Path<String>,
320	    uri: Uri,
321	) -> Response {
322	    if !valid_identifier(&name) {
323	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
324	    }
325	    let filter = match parse_key_filter(uri.query().unwrap_or("")) {
326	        Ok(filter) => filter,
327	        Err(()) => return error_response(StatusCode::BAD_REQUEST, "invalid_query"),
328	    };
329	
330	    let dir = state.data_dir.join(&name);
331	    let mut entries = match tokio::fs::read_dir(&dir).await {
332	        Ok(entries) => entries,
333	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
334	            return error_response(StatusCode::NOT_FOUND, "not_found");
335	        }
336	        Err(e) => {
337	            tracing_error(&e);
338	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
339	        }
340	    };
341	
342	    let mut records: Vec<(String, Value, SystemTime)> = Vec::new();
343	    loop {
344	        let entry = match entries.next_entry().await {
345	            Ok(Some(entry)) => entry,
346	            Ok(None) => break,
347	            Err(e) => {
348	                tracing_error(&e);
349	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
350	            }
351	        };
352	        let file_name = entry.file_name();
353	        let Some(file_name) = file_name.to_str() else {
354	            continue;
355	        };
356	        let Some(key) = file_name.strip_suffix(".json") else {
357	            continue;
358	        };
359	        // Filter on the key alone, before reading: records outside the hit
360	        // set are excluded even if their file is corrupt or unreadable.
361	        if !filter.matches(key) {
362	            continue;
363	        }
364	
365	        let result = async {
366	            let bytes = tokio::fs::read(entry.path()).await?;
367	            let modified = entry.metadata().await?.modified()?;
368	            Ok::<(Vec<u8>, SystemTime), std::io::Error>((bytes, modified))
369	        }
370	        .await;
371	        let (bytes, modified) = match result {
372	            Ok(ok) => ok,
373	            Err(e) => {
374	                tracing_error(&e);
375	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
376	            }
377	        };
378	        let value: Value = match serde_json::from_slice(&bytes) {
379	            Ok(value) => value,
380	            Err(e) => {
381	                eprintln!("corrupt record {name}/{key}: {e}");
382	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
383	            }
384	        };
385	        records.push((key.to_owned(), value, modified));
386	    }
387	
388	    // Byte-wise order on UTF-8 is Unicode code-point order.
389	    records.sort_by(|a, b| a.0.cmp(&b.0));
390	    let records: Vec<Value> = records
391	        .into_iter()
392	        .map(|(key, value, modified)| {
393	            json!({
394	                "key": key,
395	                "value": value,
396	                "updatedAt": format_rfc3339_utc(modified),
397	            })
398	        })
399	        .collect();
400	    Json(json!({ "name": name, "records": records })).into_response()
401	}
402	
403	#[tokio::main]
404	async fn main() -> Result<(), Box<dyn Error>> {
405	    let bind = env::var("VDE_BIND").unwrap_or_else(|_| "127.0.0.1:8080".to_owned());
406	    let data_dir = env::var("VDE_DATA_DIR")
407	        .map(PathBuf::from)
408	        .unwrap_or_else(|_| PathBuf::from("./data"));
409	    let state = AppState {
410	        data_dir: Arc::new(data_dir),
411	    };
412	
413	    let listener = tokio::net::TcpListener::bind(&bind).await?;
414	    let app = Router::new()
415	        .route("/health", get(health))
416	        .route("/version", get(version))
417	        .route(
418	            "/datasets/{name}/records/{key}",
419	            put(put_record).get(get_record),
420	        )
421	        .route("/datasets/{name}/records", get(list_records))
422	        .with_state(state);
423	
424	    println!("Listening on http://{}", listener.local_addr()?);
425	    axum::serve(listener, app)
426	        .with_graceful_shutdown(async {
427	            let _ = tokio::signal::ctrl_c().await;
428	        })
429	        .await?;
430	    Ok(())
431	}
