import json, subprocess, os, signal, time, threading, urllib.request, urllib.error, sys, collections

BIN = "./target/debug/versioned-data-engine"
ROOT = "/tmp/vde_conc"
PORT = 18096
B = f"http://127.0.0.1:{PORT}"
NB = 12
K = 8

os.environ.update(VDE_BIND=f"127.0.0.1:{PORT}", VDE_DATA_DIR=ROOT)

def req(method, path, body=None):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(B + path, data=data, method=method,
                               headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(r) as resp:
        return resp.status, json.load(resp)

def batch(j):
    recs = [{"key": f"b{j:02d}k{i:02d}", "value": j} for i in range(K)]
    s, _ = req("PUT", "/datasets/cc/records", {"records": recs})
    assert s == 200, s

violations = []
snapshots = 0
stop = False

def reader():
    global snapshots
    while not stop:
        try:
            _, d = req("GET", "/datasets/cc/records")
        except Exception:
            continue
        snapshots += 1
        cnt = collections.Counter()
        for r in d["records"]:
            cnt[r["key"][:4]] += 1  # b00k prefix group
        for grp, c in cnt.items():
            if c not in (0, K):
                violations.append((grp, c))

subprocess.run(["pkill", "-f", BIN], stderr=subprocess.DEVNULL)
os.system(f"rm -rf {ROOT}")
p = subprocess.Popen([BIN], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
for _ in range(50):
    try:
        urllib.request.urlopen(B + "/health", timeout=1); break
    except Exception:
        time.sleep(0.1)

try:
    # Start readers
    readers = [threading.Thread(target=reader) for _ in range(6)]
    for t in readers: t.start()

    # Fire all batches concurrently
    threads = [threading.Thread(target=batch, args=(j,)) for j in range(NB)]
    for t in threads: t.start()
    for t in threads: t.join()

    # extra churn: overwrite all batches again concurrently
    threads = [threading.Thread(target=batch, args=(j,)) for j in range(NB)]
    for t in threads: t.start()
    for t in threads: t.join()

    time.sleep(0.5)
    stop = True
    for t in readers: t.join()
finally:
    p.send_signal(signal.SIGTERM); p.wait()

# Final on-disk state via fresh server check
p = subprocess.Popen([BIN], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
for _ in range(50):
    try: urllib.request.urlopen(B + "/health", timeout=1); break
    except Exception: time.sleep(0.1)
try:
    _, d = req("GET", "/datasets/cc/records")
    got = {r["key"]: r["value"] for r in d["records"]}
    expected = {f"b{j:02d}k{i:02d}": j for j in range(NB) for i in range(K)}
    final_ok = got == expected
    # also verify updatedAt present/parsable
    import datetime
    for r in d["records"]:
        datetime.datetime.strptime(r["updatedAt"], "%Y-%m-%dT%H:%M:%SZ")
finally:
    p.send_signal(signal.SIGTERM); p.wait()

print(f"snapshots observed: {snapshots}")
print(f"partial-batch violations: {len(violations)} {violations[:5]}")
print(f"final state complete & correct: {final_ok}")
sys.exit(0 if not violations and final_ok else 1)

