import json, os, shutil, signal, subprocess, time, urllib.request, urllib.error, random, sys

BIN = "./target/debug/versioned-data-engine"
ROOT = "/tmp/vde_kill"
PORT = 18095
B = f"http://127.0.0.1:{PORT}"
N = 250          # batch keys
ROUNDS = 18

def env():
    e = dict(os.environ); e.update(VDE_BIND=f"127.0.0.1:{PORT}", VDE_DATA_DIR=ROOT); return e

def wait_up(timeout=10):
    for _ in range(int(timeout/0.05)):
        try:
            urllib.request.urlopen(B+"/health", timeout=1); return True
        except Exception: time.sleep(0.05)
    return False

def start():
    p = subprocess.Popen([BIN], env=env(), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    assert wait_up(), "start failed"
    return p

def stop_graceful(p):
    p.send_signal(signal.SIGTERM)
    try: p.wait(timeout=5)
    except Exception: p.kill()

def get_records():
    with urllib.request.urlopen(B+"/datasets/k/records") as r:
        return {x["key"]: x["value"] for x in json.load(r)["records"]}

shutil.rmtree(ROOT, ignore_errors=True)

# baseline: base-0..4 = "old"
p = start()
for i in range(5):
    req = urllib.request.Request(B+f"/datasets/k/records/base-{i}",
          data=json.dumps("old").encode(), method="PUT",
          headers={"Content-Type":"application/json"})
    urllib.request.urlopen(req)
stop_graceful(p)

fails = []
for rnd in range(ROUNDS):
    # snapshot pre-state baseline keys values must be "old" unless batch applied
    p = start()
    # launch a big batch in a worker thread
    payload = {"records": []}
    # overwrite base-0..4 with new value, add bk-000..bk-(N-1)
    for i in range(5):
        payload["records"].append({"key": f"base-{i}", "value": "new"})
    for i in range(N):
        payload["records"].append({"key": f"bk-{i:03d}", "value": i})
    data = json.dumps(payload).encode()

    import threading
    result = {}
    def do_req():
        req = urllib.request.Request(B+"/datasets/k/records", data=data, method="PUT",
              headers={"Content-Type":"application/json"})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                result["status"] = resp.status
        except Exception as e:
            result["err"] = str(e)
    t = threading.Thread(target=do_req); t.start()
    # kill at a random moment across staging + switch windows
    time.sleep(random.uniform(0.0, 0.12))
    p.kill()  # SIGKILL, no graceful cleanup
    t.join(timeout=2)

    # restart -> recovery runs
    p2 = start()
    try:
        recs = get_records()
        bk = [k for k in recs if k.startswith("bk-")]
        applied = len(bk) == N and all(recs[f"bk-{i:03d}"] == i for i in range(N))
        absent = len(bk) == 0
        # core invariant: never partial
        if not (applied or absent):
            fails.append((rnd, f"PARTIAL batch keys present: {len(bk)}/{N}"))
            continue
        # base values must agree with application state
        base_vals = {f"base-{i}": recs.get(f"base-{i}") for i in range(5)}
        if applied:
            ok_base = all(v == "new" for v in base_vals.values())
            if not ok_base: fails.append((rnd, f"applied but base not new: {base_vals}"))
        else:
            ok_base = all(v == "old" for v in base_vals.values())
            if not ok_base: fails.append((rnd, f"absent but base changed: {base_vals}"))
        # no leftover staging dirs
        left = [n for n in os.listdir(ROOT) if n.startswith(".") and ".batch-" in n]
        if left: fails.append((rnd, f"leftover journal: {left}"))
        print(f"round {rnd:02d}: {'APPLIED' if applied else 'pre-batch'} base={'new' if applied else 'old'} leftovers={len(left)}")
    finally:
        stop_graceful(p2)

print()
if fails:
    print("FAILURES:")
    for f in fails: print(" ", f)
    sys.exit(1)
print(f"ALL {ROUNDS} KILL ROUNDS RECOVERED TO A COMPLETE STATE")

